<?php
require_once __DIR__.'/bootstrap.php';require_once __DIR__.'/repository.php';require_once __DIR__.'/events.php';permit($section);
[$table,$key,$owner,$title]=event_spec($section);$id=input('id');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{review_event($section,$id,input('decision'));flash('บันทึกผลการพิจารณาสำเร็จ');redirect($section.'/?id='.rawurlencode($id));}catch(InvalidArgumentException $ex){$error=$ex->getMessage();http_response_code(409);}}
$r=$id!==''?event_record($section,$id):null;
try{[$where,$args]=event_filters($section);}catch(InvalidArgumentException $ex){abort_page(422,$ex->getMessage());}
require __DIR__.'/header.php';
if($r):$labels=event_columns($section)+['attendance_id'=>'รหัสลงเวลา','offsite_request_id'=>'รหัสคำขอ','biometric_id'=>'รหัสข้อมูลใบหน้า','latitude'=>'ละติจูด','longitude'=>'ลองจิจูด','reason'=>'เหตุผล','device_info'=>'อุปกรณ์','approved_by'=>'ผู้พิจารณา','approved_date'=>'วันที่พิจารณา','department_name'=>'แผนก']; ?>
<a class="btn btn-outline-secondary mb-3" href="<?=e(url($section.'/'))?>">กลับรายการ</a><div class="card"><div class="card-body"><dl class="detail-grid"><?php foreach($r as $name=>$value):if(in_array($name,['face_image','evidence_photo']))continue;?><div><dt><?=e($labels[$name]??$name)?></dt><dd><?=in_array($name,['approval_status','status','zone_status'])?badge($value):e($value??'—')?></dd></div><?php endforeach;?></dl>
<?php if(($section==='biometrics'&&!empty($r['face_image']))||($section==='attendance'&&!empty($r['evidence_photo']))):?><h2 class="h6">ภาพประกอบการพิจารณา</h2><img class="evidence mb-4" src="<?=e(url('attendance/image.php?kind='.$section.'&id='.$id))?>" alt="ภาพประกอบของพนักงาน" loading="lazy"><?php endif;?>
<?php if($section==='attendance'):$polygon=scalar('SELECT polygon_coordinates FROM geofence_areas WHERE area_id=?',[$r['area_id']]);?><h2 class="h6">ตำแหน่งลงเวลาและขอบเขตพื้นที่ปัจจุบัน</h2><p class="text-secondary small">จุดสีแดงคือตำแหน่งลงเวลา ขอบเขตแสดงตามข้อมูลพื้นที่ปัจจุบัน ซึ่งอาจเปลี่ยนจากวันที่ลงเวลา</p><div class="tg-map" data-map data-polygon="<?=e($polygon?:'[]')?>" data-point="<?=e(json_encode(['lat'=>(float)$r['latitude'],'lng'=>(float)$r['longitude']]))?>"></div><?php endif;?>
<?php if(allowed($section.'.write')&&in_array($r['approval_status'],['pending','รออนุมัติ'])&&($section!=='biometrics'||$r['status']==='active')):?><form method="post" class="d-flex gap-2 mt-4" data-confirm="ยืนยันผลการพิจารณารายการนี้?"><?php csrf_field();?><input type="hidden" name="id" value="<?=e($id)?>"><button class="btn btn-success" name="decision" value="approve">อนุมัติ</button><button class="btn btn-outline-danger" name="decision" value="reject">ปฏิเสธ</button></form><?php endif;?></div></div>
<?php else:
 filter_form($section);
 $join=" FROM `$table` r JOIN employees e ON e.employee_id=r.`$owner`";
 if($section==='attendance')$join.=' LEFT JOIN geofence_areas g ON g.area_id=r.area_id';
 $count=(int)scalar('SELECT COUNT(*)'.$join.$where,$args);$pages=max(1,(int)ceil($count/25));$page=min($pages,max(1,(int)input('page','1')));$offset=($page-1)*25;
 $cols=event_columns($section);$select=[];foreach(array_keys($cols) as $col)$select[]=match($col){'employee_name'=>'e.full_name employee_name','area_name'=>'g.area_name',default=>'r.'.$col};
 $rows=q('SELECT r.'.$key.','.implode(',',$select).$join.$where." ORDER BY r.`$key` DESC LIMIT 25 OFFSET $offset",$args)->fetchAll();
 ?><div class="card"><div class="card-header"><?=e($count)?> รายการ</div><div class="table-responsive"><table class="table mb-0"><thead><tr><?php foreach($cols as $label):?><th><?=e($label)?></th><?php endforeach;?><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($cols as $col=>$label):?><td><?=in_array($col,['approval_status','status','zone_status'])?badge($row[$col]):($col==='is_late'?($row[$col]?badge('มาสาย'):'—'):e($row[$col]))?></td><?php endforeach;?><td><a class="btn btn-sm btn-outline-primary" href="?id=<?=e($row[$key])?>">รายละเอียด</a></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty">ไม่พบข้อมูล</div><?php endif;?></div><div class="card-body d-flex gap-2"><span class="me-auto">หน้า <?=$page?> / <?=$pages?></span><?php foreach([$page-1=>'ก่อนหน้า',$page+1=>'ถัดไป'] as $p=>$label):if($p<1||$p>$pages)continue;?><a class="btn btn-sm btn-outline-secondary" href="?<?=e(http_build_query(array_merge($_GET,['page'=>$p])))?>"><?=$label?></a><?php endforeach;?></div></div>
<?php endif;require __DIR__.'/footer.php'; ?>
